  "Age bands": "الفئات العمرية",
  "content sources": "مصادر المحتوى",
  "23 organizational bands:": "23 فئة تنظيمية:",
  "12 monthly bands before age 1, four 3-month bands from 1 to under 2, four 6-month bands from 2 to under 4, and three yearly bands from 4 to under 7. These are product content categories, not a medical classification.": "12 فئة شهرية قبل السنة، وأربع فئات كل 3 أشهر من سنة إلى ما قبل سنتين، وأربع فئات كل 6 أشهر من سنتين إلى ما قبل 4، وثلاث فئات سنوية من 4 إلى ما قبل 7. هذه تصنيفات محتوى وليست تصنيفًا طبيًا.",
  "12 external CDC checklist checkpoints:": "12 محطة لقوائم CDC الخارجية:",
  "2, 4, 6, 9, 12, 15, 18, 24, 30, 36, 48 and 60 months. These checkpoints are separate from the 23 bands. The upper age limit of 7 years is the current product scope.": "2 و4 و6 و9 و12 و15 و18 و24 و30 و36 و48 و60 شهرًا. هذه المحطات منفصلة عن الفئات الـ23. حد 7 سنوات هو نطاق المنتج الحالي.",
  "Age is calculated from date of birth. Parent pages also support corrected-age logic for children born early. Content assigned to old broad age groups is retained as legacy content and requires review before reassignment. An age band does not imply reviewed content is available.": "يُحسب العمر من تاريخ الميلاد، وتدعم صفحات الأهل العمر المصحح للخدّج. يبقى المحتوى القديم محفوظًا ويحتاج مراجعة قبل إعادة تعيينه. وجود فئة لا يعني توفر محتوى مراجع لها.",
  "CONTENT GOVERNANCE": "حوكمة المحتوى",
  "Manage what RAFIQ": "أدر ما يعلّمه",
  "teaches and displays.": "رفيق ويعرضه.",
