  "Contact support": "تواصل مع الدعم",
  "How do I create a parent account?": "كيف أنشئ حساب ولي أمر؟",
  "Open the": "افتح",
  "registration page": "صفحة التسجيل",
  "and choose Parent. Enter your name, email and phone number, choose a password that meets the requirements, confirm it and accept the terms. After registration, follow the steps to set up your child's profile.": "واختر ولي أمر. أدخل اسمك وبريدك ورقم هاتفك، واختر كلمة مرور تستوفي المتطلبات ثم أكدها ووافق على الشروط. بعد التسجيل أكمل إعداد ملف طفلك.",
  "What should I do if I can't complete registration?": "ماذا أفعل إذا لم أتمكن من إكمال التسجيل؟",
  "Check the error message below each field. Make sure your email is correct, both passwords match, all required fields are complete and you have accepted the terms. If you still need help, use “Trouble signing up? Get help” below the registration button or contact support below.": "راجع رسالة الخطأ أسفل كل حقل. تأكد من صحة البريد وتطابق كلمتي المرور واكتمال الحقول المطلوبة والموافقة على الشروط. إذا احتجت للمساعدة، اختر «تواجه صعوبة في التسجيل؟ احصل على مساعدة» أو تواصل مع الدعم أدناه.",
  "I received an invitation from an admin. How do I start?": "وصلتني دعوة من الإدارة، كيف أبدأ؟",
  "Open the registration link in your invitation and create a parent account. The invitation guides you to registration; you choose your own password. You do not need to share your password with the admin.": "افتح رابط التسجيل في الدعوة وأنشئ حساب ولي أمر. اختر كلمة مرورك بنفسك، ولا تشاركها مع الإدارة.",
  "What if I forgot my password?": "ماذا أفعل إذا نسيت كلمة المرور؟",
  "On the login page, choose": "في صفحة الدخول اختر",
  "Forgot password": "نسيت كلمة المرور",
  "and follow the instructions. If you cannot continue, contact support. Never share your password or verification codes.": "واتبع التعليمات. إذا تعذر المتابعة، تواصل مع الدعم. لا تشارك كلمة المرور أو رموز التحقق.",
  "How do I add a child or switch between children?": "كيف أضيف طفلًا أو أتنقل بين أطفالي؟",
  "After logging in, complete your child's profile setup. To add another child, open the child menu at the top of the page and choose “Add another child”. You can also use this menu to switch between your children's profiles.": "بعد الدخول أكمل ملف طفلك. لإضافة طفل آخر، افتح قائمة الطفل أعلى الصفحة واختر «إضافة طفل آخر». يمكنك التنقل بين ملفات أطفالك من القائمة نفسها.",
  "How do I update my child's details?": "كيف أعدل بيانات طفلي؟",
  "Select your child's name at the top of a parent page to open their profile, then use the available editing options. Make sure you have selected the right child before making changes.": "اختر اسم طفلك أعلى صفحة الأهل لفتح ملفه، ثم استخدم خيارات التعديل. تأكد من اختيار الطفل الصحيح قبل التعديل.",
  "specialists": "المختصون",
  "How do I book an appointment with a specialist?": "كيف أحجز موعدًا مع مختص؟",
  "After logging in, open “Specialists” and choose “Find a specialist”. Review the specialist's profile, open the booking page, choose an available appointment and check the details before confirming.": "بعد الدخول افتح «المختصون» ثم «ابحث عن مختص». راجع الملف، وافتح صفحة الحجز، واختر موعدًا متاحًا وراجع التفاصيل قبل التأكيد.",
  "Where can I find my appointments and specialist reports?": "أين أجد مواعيدي وتقارير المختصين؟",
  "Open “My appointments” from the Specialists menu, or “Visits": "افتح «مواعيدي» من قائمة المختصين، أو «الزيارات",
  "reports” from Records. Select an appointment to review its details and report, when available.": "والتقارير» من السجلات. اختر الموعد لمراجعة تفاصيله وتقريره عند توفره.",
  "No matching answers found. Try another search or contact us.": "لا توجد إجابات مطابقة. جرّب بحثًا آخر أو تواصل معنا.",
  "Submit a support request": "إرسال طلب دعم",
  "Tell us what happened. Do not include passwords or verification codes.": "اشرح ما حدث، دون تضمين كلمات المرور أو رموز التحقق.",
  "Technical issue": "مشكلة تقنية",
  "Describe your problem": "اشرح مشكلتك",
