  "STILL NEED A HAND?": "ما زلت تحتاج للمساعدة؟",
  "Talk to us": "تحدث إلينا",
  "Message RAFIQ support on WhatsApp and describe the problem and the step where you got stuck. You do not need an account to contact us.": "راسل دعم رفيق عبر واتساب واشرح المشكلة والخطوة التي توقفت عندها. لا تحتاج إلى حساب للتواصل معنا.",
  "Never send your password or verification codes. WhatsApp opens in a new tab so you can review and send your message.": "لا ترسل كلمة المرور أو رموز التحقق. يفتح واتساب في تبويب جديد لتراجع رسالتك وترسلها.",
