  "Hitting is common at this age, when big feelings arrive faster than the words for them. Stay calm, name the feeling, and show what to do instead: \"Hands are for gentle touches.\"": "قد يظهر الضرب في هذا العمر عندما يصعب التعبير عن المشاعر بالكلمات. حافظ على هدوئك، وسمّ الشعور ووضح البديل: «نستخدم أيدينا بلطف».",
