  "How can I record a moment together?": "كيف أسجل لحظة مع طفلي؟",
  "Help me describe my baby’s responses during play": "ساعدني في وصف استجابة طفلي أثناء اللعب",
  "What should I ask about my baby’s current stage?": "ماذا أسأل عن مرحلة طفلي الحالية؟",
