  "Help me describe my toddler’s communication": "ساعدني في وصف تواصل طفلي الصغير",
  "Help me organize a question about play": "ساعدني في تنظيم سؤال عن اللعب",
  "Help me record a daily routine observation": "ساعدني في تسجيل ملاحظة عن الروتين اليومي",
  "Help me describe a play or conversation moment": "ساعدني في وصف لحظة لعب أو حديث",
  "Help me organize a question about routines": "ساعدني في تنظيم سؤال عن الروتين",
  "What would I like to discuss with a specialist?": "ما الذي أريد مناقشته مع المختص؟",
  "Help me describe a friendship or play observation": "ساعدني في وصف ملاحظة عن الصداقة أو اللعب",
  "Help me organize a question about school routines": "ساعدني في تنظيم سؤال عن الروتين المدرسي",
  "Help me record a moment of independence": "ساعدني في تسجيل لحظة استقلالية",
  "corrected age": "العمر المصحح",
  "This may require urgent medical attention. Rafiq cannot safely assess an emergency through chat. Please seek urgent medical care or contact local emergency services if your child may be in immediate danger.": "قد يتطلب الأمر عناية طبية عاجلة. لا يستطيع رفيق تقييم الطوارئ بأمان عبر المحادثة. اطلب الرعاية العاجلة أو اتصل بالطوارئ المحلية إذا كان طفلك في خطر مباشر.",
  "Clear this conversation?": "مسح هذه المحادثة؟",
  "Not enough browser storage. Download backups and free space before trying again.": "مساحة تخزين المتصفح غير كافية. نزّل نسخًا احتياطية وأخلِ مساحة ثم حاول مجددًا.",
  "The photos could not be saved or loaded. Browser storage may be unavailable. Please retry.": "تعذر حفظ الصور أو تحميلها. قد يكون تخزين المتصفح غير متاح. حاول مجددًا.",
  "Close other album tabs and reload to finish opening photo storage.": "أغلق تبويبات الألبوم الأخرى وأعد التحميل لإكمال فتح تخزين الصور.",
  "Photo storage changed in another tab. Reload this page.": "تغير تخزين الصور في تبويب آخر. أعد تحميل الصفحة.",
  "Transaction aborted": "أُلغيت العملية",
  "No memories match your search.": "لا توجد ذكريات تطابق بحثك.",
  "Choose between 1 and 20 photos.": "اختر من صورة إلى 20 صورة.",
  "Persistent storage granted. Keep downloaded backups too; manually clearing site data still removes photos.": "تم منح التخزين الدائم. احتفظ بنسخ منزّلة أيضًا؛ فمسح بيانات الموقع يدويًا يحذف الصور.",
  "Persistent storage was not granted or is unavailable. Keep downloaded backups of your photos.": "لم يُمنح التخزين الدائم أو هو غير متاح. احتفظ بنسخ منزّلة من صورك.",
  "Persistent storage is unavailable. Download your photos to keep backups.": "التخزين الدائم غير متاح. نزّل صورك للاحتفاظ بنسخ احتياطية.",
  "My Child": "طفلي",
  "Checking and saving photos…": "جارٍ التحقق من الصور وحفظها…",
  "A little memory": "ذكرى صغيرة",
  "could not be opened": "تعذر فتحها",
  "Details saved.": "حُفظت التفاصيل.",
  "Photo deleted from this browser.": "حُذفت الصورة من هذا المتصفح.",
  "Included from your concern summary. Edit it below; it will be shared only when you confirm this booking.": "مرفق من ملخص ما يقلقك. يمكنك تعديله أدناه؛ لن تتم مشاركته إلا بعد تأكيد الحجز.",
  "Remove included note": "إزالة الملاحظة المرفقة",
  "We could not remove the saved draft. Please try again.": "تعذر إزالة المسودة المحفوظة. حاول مجددًا.",
  "Your edited note could not be saved for another visit. It is still visible in this form.": "تعذر حفظ الملاحظة المعدلة للزيارة التالية. ما زالت ظاهرة في هذا النموذج.",
  "Not specified": "غير محدد",
  "Online Consultation": "استشارة عن بُعد",
  "In-person Consultation": "استشارة حضورية",
  "This specialist has not configured consultation types yet.": "لم يحدد هذا المختص أنواع الاستشارات بعد.",
  "Remote consultation appointment with the specialist.": "موعد استشارة عن بُعد مع المختص.",
