  "Early Years": "السنوات الأولى",
  "Early Childhood": "الطفولة المبكرة",
  "School Age": "سن المدرسة",
  "Uses sounds, gestures or words to communicate": "يستخدم الأصوات أو الإشارات أو الكلمات للتواصل",
  "Notice how your child tries to express needs, interests and attention.": "لاحظ كيف يعبّر طفلك عن احتياجاته واهتماماته وانتباهه.",
  "Engages with familiar people": "يتفاعل مع الأشخاص المألوفين",
  "Observe eye contact, shared play, smiles and interest in familiar people.": "لاحظ التواصل البصري واللعب المشترك والابتسامات والاهتمام بالمألوفين.",
  "Builds movement and coordination skills": "يبني مهارات الحركة والتناسق",
  "Notice changes in sitting, walking, reaching, climbing or hand use.": "لاحظ تغيرات الجلوس أو المشي أو الوصول أو التسلق أو استخدام اليد.",
  "Explores toys and everyday objects": "يستكشف الألعاب والأشياء اليومية",
  "Observe curiosity, cause-and-effect play and interest in new objects.": "لاحظ الفضول ولعب السبب والنتيجة والاهتمام بالأشياء الجديدة.",
  "Participates in everyday routines": "يشارك في الروتين اليومي",
  "Notice involvement in eating, dressing, washing and simple routines.": "لاحظ المشاركة في الأكل واللباس والغسل والروتين البسيط.",
  "Communicates ideas and everyday experiences": "يعبّر عن الأفكار والخبرات اليومية",
  "Notice how your child explains needs, events, stories and questions.": "لاحظ كيف يشرح طفلك الاحتياجات والأحداث والقصص والأسئلة.",
  "Participates in play with other children": "يشارك في اللعب مع الأطفال",
  "Observe taking turns, sharing ideas and joining group play.": "لاحظ تبادل الأدوار والأفكار والمشاركة الجماعية.",
  "Uses growing coordination in play": "يستخدم تناسقًا متزايدًا في اللعب",
  "Notice running, jumping, drawing, building and other coordinated activities.": "لاحظ الجري والقفز والرسم والبناء والأنشطة المنسقة.",
  "Follows routines and simple sequences": "يتبع الروتين وتسلسلات بسيطة",
  "Observe memory, simple problem-solving and understanding everyday instructions.": "لاحظ الذاكرة وحل المشكلات البسيطة وفهم التعليمات اليومية.",
  "Shows growing independence": "يُظهر استقلالية متزايدة",
  "Notice participation in dressing, tidying, eating and personal routines.": "لاحظ المشاركة في اللباس والترتيب والأكل والعناية الشخصية.",
  "Explains thoughts, questions and experiences": "يشرح الأفكار والأسئلة والخبرات",
  "Notice how your child communicates at home, school and with peers.": "لاحظ تواصل طفلك في المنزل والمدرسة ومع الأقران.",
  "Builds and maintains friendships": "يبني صداقات ويحافظ عليها",
  "Observe cooperation, conflict resolution and understanding other perspectives.": "لاحظ التعاون وحل الخلافات وفهم وجهات النظر الأخرى.",
  "Uses coordination in daily activities": "يستخدم التناسق في الأنشطة اليومية",
  "Notice confidence in play, sports, handwriting and practical tasks.": "لاحظ الثقة في اللعب والرياضة والكتابة والمهام العملية.",
  "Organizes and completes age-appropriate tasks": "ينظم وينهي مهام مناسبة للعمر",
  "Observe attention, planning, school routines and problem-solving.": "لاحظ الانتباه والتخطيط والروتين المدرسي وحل المشكلات.",
  "Takes responsibility for regular routines": "يتحمل مسؤولية الروتين المعتاد",
  "Notice independence with belongings, hygiene, homework and simple responsibilities.": "لاحظ الاستقلالية في الأغراض والنظافة والواجبات والمسؤوليات البسيطة.",
  "Expresses opinions and discusses complex topics": "يعبّر عن الرأي ويناقش موضوعات مركبة",
  "Notice communication about school, relationships, choices and emotions.": "لاحظ الحديث عن المدرسة والعلاقات والخيارات والمشاعر.",
  "Navigates friendships and social boundaries": "يتعامل مع الصداقات والحدود الاجتماعية",
  "Observe communication, peer relationships and respect for boundaries.": "لاحظ التواصل وعلاقات الأقران واحترام الحدود.",
  "Maintains healthy activity and self-care routines": "يحافظ على النشاط والعناية بالنفس",
