  "We couldn’t save the profile in this browser. Check that browser storage is available, then try again.": "تعذر حفظ الملف في هذا المتصفح. تحقق من توفر التخزين وحاول مجددًا.",
  "Ⅱ Pause background": "Ⅱ إيقاف الخلفية",
  "We couldn’t read your saved profile in this browser. Check that browser storage is available, then reload this page.": "تعذر قراءة ملفك المحفوظ. تحقق من توفر التخزين ثم أعد تحميل الصفحة.",
