  "Your personal follow-up is saved. Your specialist’s original report has not been changed.": "حُفظت متابعتك الشخصية. لم يتغير تقرير المختص الأصلي.",
  "We couldn’t save all follow-up details. Check browser storage and try again; your original report has not been changed.": "تعذر حفظ جميع تفاصيل المتابعة. تحقق من التخزين وحاول مجددًا؛ لم يتغير التقرير الأصلي.",
  "We couldn’t read your saved profile or concern. Check browser storage, then reload. Existing records have not been changed.": "تعذر قراءة الملف أو ما يقلقك. تحقق من التخزين وأعد التحميل. لم تتغير السجلات الحالية.",
