  "Choose an answer": "اختر إجابة",
  "See my next step →": "شاهد خطوتي التالية ←",
  "Browse a directory topic related to your concern. Check each specialist’s experience with your child’s age, fees and availability before booking.": "تصفح تخصصًا مرتبطًا بما يقلقك. تحقق من خبرة المختص بعمر طفلك والرسوم والتوفر قبل الحجز.",
  "This preview is shortened to the 500-character booking limit. Your full answers remain saved above.": "اختُصرت المعاينة إلى حد الحجز البالغ 500 حرف. تبقى إجاباتك كاملة محفوظة أعلاه.",
  "Only this note will be added to the booking draft. You can review it again before confirmation.": "ستُضاف هذه الملاحظة فقط إلى مسودة الحجز. يمكنك مراجعتها قبل التأكيد.",
  "An original English SWYC": "نموذج SWYC أصلي باللغة الإنجليزية لعمر",
  "-month form is available for the selected screening age. It is a broad developmental form, not a test specific to": "شهرًا متاح لعمر الفحص المحدد. هو نموذج تطوري عام وليس اختبارًا مخصصًا لـ",
  ". Review the choice and completed form with your care team.": ". راجع الاختيار والنموذج المكتمل مع فريق الرعاية.",
  "Ask your care team which screening tool is appropriate for this concern and age. The original SWYC form cannot be selected here with the current age details.": "اسأل فريق الرعاية عن أداة الفحص المناسبة للعمر وما يقلقك. لا يمكن اختيار نموذج SWYC الأصلي ببيانات العمر الحالية.",
  "Open original SWYC form ↗": "افتح نموذج SWYC الأصلي ↗",
  "This guided observation flow covers ages 0–6. You can still contact a specialist.": "يغطي مسار الملاحظة الأعمار 0–6. يمكنك التواصل مع مختص أيضًا.",
  "Choose the area that is worrying you, or select I’m not sure.": "اختر المجال الذي يقلقك أو اختر «لست متأكدًا».",
  "We couldn’t save your starting point. Check browser storage and try again.": "تعذر حفظ نقطة البداية. تحقق من التخزين وحاول مجددًا.",
  "Please add your observation or choose an answer.": "أضف ملاحظتك أو اختر إجابة.",
  "We couldn’t save this step. Your existing records have not been removed. Please try again.": "تعذر حفظ الخطوة. لم تُحذف السجلات الحالية. حاول مجددًا.",
  "This child is now outside the guided age range. Their saved summary is still available to discuss with a clinician.": "أصبح عمر الطفل خارج نطاق المسار. يبقى ملخصه المحفوظ متاحًا لمناقشته مع الطبيب.",
  "We couldn’t prepare your booking preference. You can still contact a specialist using the navigation.": "تعذر تجهيز تفضيل الحجز. يمكنك التواصل مع مختص من قائمة التنقل.",
  "TEAM UP Center at Boston Medical Center": "مركز TEAM UP في مركز بوسطن الطبي",
  "Does your child use sounds, gestures, words, or other ways to communicate needs and interests?": "هل يستخدم طفلك الأصوات أو الإشارات أو الكلمات أو طرقًا أخرى للتعبير عن الاحتياجات والاهتمامات؟",
  "Social Interaction": "التفاعل الاجتماعي",
  "Does your child show interest in interacting with familiar people?": "هل يبدي طفلك اهتمامًا بالتفاعل مع أشخاص مألوفين؟",
  "Is your child developing new movement or coordination skills over time?": "هل يطور طفلك مهارات حركة أو تناسق جديدة مع الوقت؟",
  "Does your child explore toys, objects, or activities with curiosity?": "هل يستكشف طفلك الألعاب أو الأشياء أو الأنشطة بفضول؟",
  "Everyday Skills": "مهارات الحياة اليومية",
  "Does your child participate in everyday routines such as eating, dressing, or washing?": "هل يشارك طفلك في روتين الأكل أو اللباس أو الغسل؟",
