  "Can your child usually recover from everyday frustration with support?": "هل يستطيع طفلك عادة تجاوز الإحباط اليومي مع الدعم؟",
  "Can your child follow familiar routines and simple instructions?": "هل يستطيع طفلك اتباع روتين مألوف وتعليمات بسيطة؟",
  "Does your child show growing independence in everyday activities?": "هل يظهر طفلك استقلالية متزايدة في الأنشطة اليومية؟",
