  "Can your teenager usually communicate needs, opinions, and concerns?": "هل يستطيع ابنك المراهق عادة التعبير عن الاحتياجات والآراء والمخاوف؟",
  "Social Development": "التطور الاجتماعي",
  "Does your teenager generally navigate friendships and social boundaries appropriately?": "هل يتعامل ابنك المراهق مع الصداقات والحدود الاجتماعية بشكل مناسب عمومًا؟",
