  "Self-harm or Suicide Concern": "مخاوف إيذاء النفس أو الانتحار",
  "This may require urgent support. Stay with the person when possible and seek immediate professional or emergency assistance.": "قد يتطلب هذا دعمًا عاجلًا. ابقَ مع الشخص إن أمكن واطلب مساعدة مهنية أو طارئة فورية.",
