  "Reviewed guidance that can support the RAFIQ parent assistant.": "إرشادات مراجَعة يمكنها دعم مساعد الأهل في رفيق.",
  "Knowledge entries should be educational, cautious and suitable for parent guidance. They must not present AI output as diagnosis or medical certainty.": "ينبغي أن تكون مدخلات المعرفة تعليمية وحذرة ومناسبة لإرشاد الأهل. لا تُعرض مخرجات الذكاء الاصطناعي بوصفها تشخيصًا أو يقينًا طبيًا.",
