  "Uses words or gestures to communicate needs": "يستخدم الكلمات أو الإشارات للتعبير عن احتياجاته",
  "A communication milestone used as age-appropriate developmental guidance.": "إنجاز تواصلي يُستخدم كإرشاد تطوري مناسب للعمر.",
  "Participates in cooperative play": "يشارك في اللعب التعاوني",
  "A social-development milestone for preschool and early school-age children.": "إنجاز اجتماعي لمرحلة ما قبل المدرسة وبداياتها.",
  "Uses increasingly organized problem-solving": "يستخدم حل مشكلات أكثر تنظيمًا",
  "A general developmental milestone for school-age children.": "إنجاز تطوري عام لأطفال سن المدرسة.",
  "Develops greater independence and self-awareness": "يطور استقلالية ووعيًا ذاتيًا أكبر",
  "A broad adolescent developmental milestone.": "إنجاز تطوري عام للمراهقة.",
  "Does your child regularly use sounds, gestures or words to communicate with you?": "هل يستخدم طفلك الأصوات أو الإشارات أو الكلمات بانتظام للتواصل معك؟",
  "Social Communication": "التواصل الاجتماعي",
  "Does your child usually engage with other children during play?": "هل يتفاعل طفلك عادة مع الأطفال الآخرين أثناء اللعب؟",
  "Does your child frequently struggle to stay focused during age-appropriate tasks?": "هل يواجه طفلك صعوبة متكررة في التركيز أثناء مهام مناسبة لعمره؟",
  "Have there been persistent changes in mood or everyday functioning that concern you?": "هل توجد تغيرات مستمرة في المزاج أو الأداء اليومي تقلقك؟",
  "Speech & Communication Concerns": "مخاوف النطق والتواصل",
  "Guidance for parents who have concerns about early communication development.": "إرشادات للأهل القلقين بشأن تطور التواصل المبكر.",
  "Use simple language, respond to communication attempts and create regular opportunities for interaction.": "استخدم لغة بسيطة واستجب لمحاولات التواصل ووفر فرص تفاعل منتظمة.",
  "Avoid comparing the child constantly with other children or pressuring them to perform.": "تجنب المقارنة المستمرة بالأطفال الآخرين أو الضغط على الطفل ليؤدي.",
  "Consider professional guidance when concerns are persistent, significant or affecting everyday communication.": "فكر في الإرشاد المهني إذا استمرت المخاوف أو اشتدت أو أثرت في التواصل اليومي.",
  "Tantrums & Big Emotions": "نوبات الغضب والمشاعر القوية",
  "Practical guidance for understanding emotional outbursts in younger children.": "إرشادات عملية لفهم نوبات الانفعال لدى الأطفال الصغار.",
  "Use predictable routines, calm boundaries and age-appropriate emotion language.": "استخدم روتينًا متوقعًا وحدودًا هادئة ولغة مشاعر مناسبة للعمر.",
  "Avoid escalating arguments or using inconsistent consequences.": "تجنب تصعيد الجدال أو العواقب غير الثابتة.",
  "Seek professional support when behavior becomes severe, unsafe or consistently disrupts daily functioning.": "اطلب الدعم المهني إذا اشتد السلوك أو أصبح غير آمن أو عطل الحياة اليومية باستمرار.",
  "Supportive guidance when a school-age child is struggling academically.": "إرشادات داعمة عند تعثر الطفل دراسيًا.",
  "Observe patterns, communicate with the school and break tasks into manageable steps.": "لاحظ الأنماط وتواصل مع المدرسة وقسّم المهام إلى خطوات ممكنة.",
  "Avoid labeling the child as lazy or comparing grades with siblings or classmates.": "تجنب وصف الطفل بالكسل أو مقارنة درجاته بإخوته وزملائه.",
  "Professional evaluation may be useful when learning difficulties persist despite appropriate support.": "قد يفيد التقييم المهني عند استمرار صعوبات التعلم رغم الدعم المناسب.",
  "Guidance for families navigating stress related to school expectations and performance.": "إرشاد للعائلات في التعامل مع الضغط المرتبط بالتوقعات والأداء الدراسي.",
  "Keep communication open, support realistic planning and make room for rest.": "أبقِ الحوار مفتوحًا وادعم التخطيط الواقعي وخصص وقتًا للراحة.",
  "Avoid defining the teenager's worth entirely through academic performance.": "تجنب ربط قيمة المراهق بأدائه الدراسي وحده.",
  "Seek professional support if stress significantly affects sleep, mood, safety or everyday functioning.": "اطلب الدعم المهني إذا أثر الضغط بوضوح في النوم أو المزاج أو السلامة أو الأداء اليومي.",
  "Building Predictable Family Routines": "بناء روتين عائلي متوقع",
  "Simple ways consistent routines can support everyday family life.": "طرق بسيطة لروتين ثابت يدعم الحياة العائلية اليومية.",
  "Use clear, realistic routines that fit your family's needs. Keep expectations age-appropriate and adjust routines when circumstances change.": "استخدم روتينًا واضحًا وواقعيًا يناسب عائلتك وعمر طفلك، وعدّله عند تغير الظروف.",
  "Supporting Early Communication": "دعم التواصل المبكر",
  "Everyday interaction ideas for parents of younger children.": "أفكار تفاعل يومية لأهل الأطفال الصغار.",
  "Talk during daily activities, follow your child's attention and respond to sounds, gestures and words. Keep interaction warm and pressure-free.": "تحدث خلال الأنشطة اليومية واتبع اهتمام طفلك واستجب للأصوات والإشارات والكلمات. اجعل التفاعل دافئًا ودون ضغط.",
  "Supporting Healthy Study Habits": "دعم عادات دراسة صحية",
  "Create realistic routines for homework, breaks and independent learning.": "ابنِ روتينًا واقعيًا للواجبات والاستراحات والتعلم المستقل.",
  "Use manageable study periods, predictable breaks and supportive feedback. Focus on consistency rather than perfection.": "استخدم فترات دراسة ممكنة واستراحات متوقعة وملاحظات داعمة. ركز على الاستمرارية بدل الكمال.",
  "23 organizational age bands from birth to under 7 years, shared with parent pages. Boundaries use months; the upper limit is excluded.": "23 فئة تنظيمية من الولادة إلى ما دون 7 سنوات، مشتركة مع صفحات الأهل. تُحتسب الحدود بالأشهر ولا يشمل النطاق حده الأعلى.",
  "DEVELOPMENT CONTENT": "محتوى التطور",
